package dev.tacticalcombat.client.ui;

import java.util.*;
import net.minecraft.client.font.TextRenderer;
import net.minecraft.text.Text;

/** Six allocation rows; persisted method and score constraints are also enforced by the server. */
public final class AbilityWorkspace {
    public static final Map<String,String> NAMES=Map.of("str","Strength","dex","Dexterity","con","Constitution","int","Intelligence","wis","Wisdom","cha","Charisma");
    public record Layout(int columns,int stride,int top) {}
    public static Layout layout(int width){return new Layout(1,30,88);}
    public static Layout layout(int width,int height){return new Layout(1,width<120?60:width<220?42:Math.clamp((height-100)/6,28,40),88);}
    private AbilityWorkspace() {}
    public static List<WizardModel.ScoreMethod> visibleMethods(CreatorDraftState state){return state.legacyArray()?List.of(WizardModel.ScoreMethod.POINT_BUY,WizardModel.ScoreMethod.MANUAL,WizardModel.ScoreMethod.STANDARD_ARRAY):List.of(WizardModel.ScoreMethod.POINT_BUY,WizardModel.ScoreMethod.MANUAL);}
    public static void build(CharacterCanvas pane,TextRenderer font,CreatorDraftState state,Runnable rebuild,boolean pending,java.util.function.Consumer<WizardModel.ScoreMethod> change){int x=6,w=pane.getWidth()-12;var modes=visibleMethods(state);int bw=(w-4*(modes.size()-1))/modes.size();for(int i=0;i<modes.size();i++){var mode=modes.get(i);String title=mode==WizardModel.ScoreMethod.POINT_BUY?"Point Buy":mode==WizardModel.ScoreMethod.MANUAL?"Manual / External":"Legacy Standard Array";var button=pane.control("mode:"+mode,new RpgButton(x+i*(bw+4),2,bw,18,title,"",()->{if(!pending&&mode!=state.method&&!(mode==WizardModel.ScoreMethod.MANUAL&&state.method==WizardModel.ScoreMethod.EXTERNAL_ROLLS))change.accept(mode);}).selected(state.method==mode||mode==WizardModel.ScoreMethod.MANUAL&&state.method==WizardModel.ScoreMethod.EXTERNAL_ROLLS).hint(title));button.active=!pending;}
        String help=help(state.method);int helpHeight=font.getTextHandler().wrapLines(help,w-14,net.minecraft.text.Style.EMPTY).size()*12+28;pane.panel("Method Help",x,25,w,helpHeight);pane.wrapped(help,x+7,48,w-14,RpgTheme.TEXT);int helpBottom=25+helpHeight;int budgetHeight=state.method==WizardModel.ScoreMethod.POINT_BUY?22:0;if(budgetHeight>0){pane.panel("",x,helpBottom+2,w,20);pane.liveLabel(()->w<220?compactBudget(state):status(state),x+7,helpBottom+7,w-14,RpgTheme.GOLD);}var base=layout(w,pane.getHeight());int top=Math.max(base.top(),helpBottom+budgetHeight+6);var geometry=new Layout(1,w<120?60:w<220?42:Math.clamp((pane.getHeight()-top-12)/6,28,40),top);boolean tiny=w<220,veryTiny=w<120;int labelW=Math.max(32,w-138),scoreX=tiny?x+24:x+labelW+24;
        for(int i=0;i<6;i++){String key=CreatorDraftState.ABILITIES.get(i);int y=geometry.top()+i*geometry.stride(),h=geometry.stride()-4;pane.panel("",x,y,w,h);pane.icon(key,x+5,tiny?y+3:y+(h-20)/2,tiny?16:20);pane.boldLabel(tiny?key.toUpperCase(Locale.ROOT):NAMES.get(key),x+29,tiny?y+4:y+(h-9)/2,tiny?w-30:labelW-30,RpgTheme.GOLD);int controlY=tiny?y+(veryTiny?20:17):y+2,controlH=tiny?19:h-4,inputW=30;var field=new CenteredScoreField(font,scoreX,controlY,inputW,controlH,Text.literal(NAMES.get(key)));field.setText(state.scores.get(key));field.setChangedListener(v->state.scores.put(key,v));field.setEditable(!pending&&state.method!=WizardModel.ScoreMethod.STANDARD_ARRAY);pane.control(key,field);
            var minus=pane.control("minus:"+key,new RpgButton(scoreX-24,controlY,22,controlH,state.method==WizardModel.ScoreMethod.STANDARD_ARRAY?"←":"−","",()->adjust(state,key,-1,field,pending,rebuild)).accessible("Decrease "+NAMES.get(key)).hint(state.method==WizardModel.ScoreMethod.STANDARD_ARRAY?"Swap this array value with the preceding ability":"Decrease score"));var plus=pane.control("plus:"+key,new RpgButton(scoreX+inputW+2,controlY,22,controlH,state.method==WizardModel.ScoreMethod.STANDARD_ARRAY?"→":"+","",()->adjust(state,key,1,field,pending,rebuild)).accessible("Increase "+NAMES.get(key)).hint(state.method==WizardModel.ScoreMethod.STANDARD_ARRAY?"Swap this array value with the next ability":"Increase score"));minus.active=plus.active=!pending;int modX=veryTiny?scoreX:scoreX+inputW+27,modY=veryTiny?y+42:controlY,modH=veryTiny?14:controlH;pane.panel("",modX,modY,29,modH);pane.liveLabel(()->modifier(state.scores.get(key)),modX+5,modY+(modH-9)/2,24,RpgTheme.GOLD);pane.tooltip(modX,modY,29,modH,NAMES.get(key)+" modifier: derived from this score");}
        int bottom=geometry.top()+6*geometry.stride()+4;pane.wrapped("Racial increases are manual. Enter them explicitly in Manual / External mode; no in-game rolls are generated.",x,bottom,w,RpgTheme.MUTED);
    }
    public static String help(WizardModel.ScoreMethod method){return switch(method){case STANDARD_ARRAY->"Assign each of the six preset scores to one ability. Arrows swap adjacent assignments; each score is used once.";case POINT_BUY->"Spend up to 27 points to assign ability scores. Scores range from 8 to 15; 14 and 15 cost two points per increase.";default->"Enter your ability scores directly (1–30). External rolls and racial increases are entered manually.";};}
    private static String compactBudget(CreatorDraftState state){try{return "Points: "+WizardModel.pointRemaining(state.scoreValues())+" / 27";}catch(RuntimeException invalid){return invalid.getMessage();}}
    public static String status(CreatorDraftState state){try{var values=state.scoreValues();return state.method==WizardModel.ScoreMethod.POINT_BUY?"Ability Points Remaining: "+WizardModel.pointRemaining(values)+" / 27":state.method==WizardModel.ScoreMethod.STANDARD_ARRAY?"15 · 14 · 13 · 12 · 10 · 8 — swap arrows assign each once":"Manual / External · effective scores · unverified rolls";}catch(RuntimeException invalid){return invalid.getMessage();}}
    private static String modifier(String v){try{int m=WizardModel.modifier(Integer.parseInt(v));return (m>=0?"+":"")+m;}catch(RuntimeException invalid){return "—";}}
    private static void adjust(CreatorDraftState state,String key,int delta,CenteredScoreField field,boolean pending,Runnable rebuild){if(pending)return;if(state.method==WizardModel.ScoreMethod.STANDARD_ARRAY){int index=CreatorDraftState.ABILITIES.indexOf(key);String other=CreatorDraftState.ABILITIES.get(Math.floorMod(index+delta,6)),value=state.scores.get(key);state.scores.put(key,state.scores.get(other));state.scores.put(other,value);rebuild.run();return;}try{int value=Integer.parseInt(state.scores.get(key)),lo=state.method==WizardModel.ScoreMethod.POINT_BUY?8:1,hi=state.method==WizardModel.ScoreMethod.POINT_BUY?15:30,next=Math.clamp(value+delta,lo,hi);if(state.method==WizardModel.ScoreMethod.POINT_BUY){if(delta>0){var scores=new LinkedHashMap<>(state.scoreValues());scores.put(key,next);if(WizardModel.pointRemaining(scores)<0)return;}}field.setText(Integer.toString(next));}catch(RuntimeException ignored){}}
}
